        boolean addIndent = true;
        CharSequence result = textStyle.pad(addIndent, text);
        assertNotNull(result);
        assertTrue(result.length() > text.length()); // Ensure padding increases length
        assertTrue(result.toString().contains(text.toString())); // Ensure original text is preserved
